INSERT INTO `catalogo_rango_desempeno` (`rango_id`, `codigo`, `nombre_completo`, `limite_inferior`, `limite_superior`, `color_hex`, `descripcion_cualitativa`) VALUES (1, 'Deterioro', '1. Deterioro (<40)', 0.0, 40.0, '#fd0200', 'Situación fiscal crítica: alta dependencia de transferencias, bajo ahorro corriente y elevado endeudamiento. Requiere intervención urgente del nivel central.') ON DUPLICATE KEY UPDATE `codigo`=VALUES(`codigo`), `nombre_completo`=VALUES(`nombre_completo`), `limite_inferior`=VALUES(`limite_inferior`), `limite_superior`=VALUES(`limite_superior`), `color_hex`=VALUES(`color_hex`), `descripcion_cualitativa`=VALUES(`descripcion_cualitativa`);
INSERT INTO `catalogo_rango_desempeno` (`rango_id`, `codigo`, `nombre_completo`, `limite_inferior`, `limite_superior`, `color_hex`, `descripcion_cualitativa`) VALUES (2, 'Riesgo', '2. Riesgo (>=40 y <60)', 40.0, 60.0, '#fddd00', 'Desempeño fiscal débil, con vulnerabilidades fiscales que pueden agravarse ante choques externos si no se adoptan medidas correctivas.') ON DUPLICATE KEY UPDATE `codigo`=VALUES(`codigo`), `nombre_completo`=VALUES(`nombre_completo`), `limite_inferior`=VALUES(`limite_inferior`), `limite_superior`=VALUES(`limite_superior`), `color_hex`=VALUES(`color_hex`), `descripcion_cualitativa`=VALUES(`descripcion_cualitativa`);
INSERT INTO `catalogo_rango_desempeno` (`rango_id`, `codigo`, `nombre_completo`, `limite_inferior`, `limite_superior`, `color_hex`, `descripcion_cualitativa`) VALUES (3, 'Vulnerable', '3. Vulnerable (>=60 y <70)', 60.0, 70.0, '#2476c5', 'Desempeño aceptable pero con áreas de mejora. El departamento mantiene equilibrios básicos aunque enfrenta restricciones fiscales.') ON DUPLICATE KEY UPDATE `codigo`=VALUES(`codigo`), `nombre_completo`=VALUES(`nombre_completo`), `limite_inferior`=VALUES(`limite_inferior`), `limite_superior`=VALUES(`limite_superior`), `color_hex`=VALUES(`color_hex`), `descripcion_cualitativa`=VALUES(`descripcion_cualitativa`);
INSERT INTO `catalogo_rango_desempeno` (`rango_id`, `codigo`, `nombre_completo`, `limite_inferior`, `limite_superior`, `color_hex`, `descripcion_cualitativa`) VALUES (4, 'Solvente', '4. Solvente (>=70 y <80)', 70.0, 80.0, '#0046b1', 'Desempeño fiscal sólido. Buena capacidad de ahorro, baja dependencia de transferencias y adecuada ejecución presupuestal.') ON DUPLICATE KEY UPDATE `codigo`=VALUES(`codigo`), `nombre_completo`=VALUES(`nombre_completo`), `limite_inferior`=VALUES(`limite_inferior`), `limite_superior`=VALUES(`limite_superior`), `color_hex`=VALUES(`color_hex`), `descripcion_cualitativa`=VALUES(`descripcion_cualitativa`);
INSERT INTO `catalogo_rango_desempeno` (`rango_id`, `codigo`, `nombre_completo`, `limite_inferior`, `limite_superior`, `color_hex`, `descripcion_cualitativa`) VALUES (5, 'Sostenible', '5. Sostenible (>=80)', 80.0, 105.0, '#0e7c66', 'Desempeño fiscal sobresaliente. Alta eficiencia en recaudo, inversión y gestión financiera. Referente nacional de buenas prácticas fiscales.') ON DUPLICATE KEY UPDATE `codigo`=VALUES(`codigo`), `nombre_completo`=VALUES(`nombre_completo`), `limite_inferior`=VALUES(`limite_inferior`), `limite_superior`=VALUES(`limite_superior`), `color_hex`=VALUES(`color_hex`), `descripcion_cualitativa`=VALUES(`descripcion_cualitativa`);
